```rust
#[tokio::test]
async fn gate_repro_concurrent_manifest_renames_create_two_destinations() {
    use lance_namespace::models::{RenameTableRequest, TableExistsRequest};

    let (namespace, _temp_dir) = create_test_namespace().await;
    let mut create = CreateTableRequest::new();
    create.id = Some(vec!["source".to_string()]);
    namespace
        .create_table(create, Bytes::from(create_non_empty_test_ipc_data()))
        .await
        .unwrap();

    let mut first = RenameTableRequest::new("first".to_string());
    first.id = Some(vec!["source".to_string()]);
    let mut second = RenameTableRequest::new("second".to_string());
    second.id = Some(vec!["source".to_string()]);

    let (a, b) = tokio::join!(
        namespace.rename_table(first),
        namespace.rename_table(second)
    );
    let success_count = usize::from(a.is_ok()) + usize::from(b.is_ok());

    let mut first_exists = TableExistsRequest::new();
    first_exists.id = Some(vec!["first".to_string()]);
    let mut second_exists = TableExistsRequest::new();
    second_exists.id = Some(vec!["second".to_string()]);
    let destination_count =
        usize::from(namespace.table_exists(first_exists).await.is_ok())
            + usize::from(namespace.table_exists(second_exists).await.is_ok());

    assert_eq!((success_count, destination_count), (1, 1));
}
